with base as (select * from transactions where is_flagged = false and (txn_type in ('REFUND', 'FEE') or hour(txn_time) between 9 and 15)), transactions_stats as (select merchant, sort_array(collect_set(txn_type)) as txn_type_list, count(case when merchant = 'Starbucks' then 1 end) as starbucks_count from base group by merchant) select merchant, txn_type_list, starbucks_count from transactions_stats where starbucks_count > 5 order by starbucks_count desc, merchant limit 10;
